    "title": "The Adventures of Pinocchio",
    "category": "stories",
    "level": "A2",
    "source": "The Adventures of Pinocchio (1883) - Carlo Collodi",
    "image_url": "https://images.unsplash.com/photo-1541701494587-cb58502866ab?w=800",
